/**
 * The vendor floor: the vendor's own rendering of one line in one voice,
 * captured outside any conversation and committed with its provenance.
 *
 * Parity means "at least as good as the vendor's own demo", so the comparison
 * needs a recording of that demo that cannot drift, cannot be regenerated by a
 * live run, and cannot be swapped without the change being visible. The floor
 * is therefore a checked-in PCM WAV plus a JSON sidecar recording the voice,
 * the line, the date and how it was produced, and the loader refuses anything
 * that does not agree with it.
 *
 * The loader has no empty state. A missing capture, a missing sidecar, a
 * sidecar that fails to parse, a file the metric library cannot decode, audio
 * that no longer matches its hash and a format the sidecar misdescribes are
 * each a named `VendorFloorError` carrying the command that produces a real
 * one. Callers cannot accidentally compare against silence or a default.
 */
import { createHash } from "node:crypto";
import { existsSync, readFileSync } from "node:fs";
import { basename, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import {
  AudioFactsError,
  decodeWav,
  type AudioFacts,
  type DecodedAudio,
} from "./format-facts";

export const VENDOR_FLOOR_SCHEMA_VERSION = 1;

/** The featured voice and its Locale: the first subject re-proved on the corrected playback. */
export const VENDOR_FLOOR_VOICE = "anna";
export const VENDOR_FLOOR_LOCALE = "en";

/** Committed evidence, resolved from this module so no cwd can move it. */
export const VENDOR_FLOOR_DIR = fileURLToPath(
  new URL("../../../evidence/vendor-floor/", import.meta.url),
);

/** The one command that produces a floor without an owner-supplied recording. */
export const VENDOR_FLOOR_COMMAND = `npm run voice:vendor-floor -- --voice ${VENDOR_FLOOR_VOICE} --locale ${VENDOR_FLOOR_LOCALE}`;

/**
 * How the audio came to exist. The two are not interchangeable evidence:
 * `vendor-tts-http` is reproducible by the script, `playground-recording` is a
 * human capture of the vendor's browser playground.
 */
export const VENDOR_FLOOR_METHODS = ["vendor-tts-http", "playground-recording"] as const;

export type VendorFloorMethod = (typeof VENDOR_FLOOR_METHODS)[number];

export type VendorFloorProvenance = {
  schemaVersion: typeof VENDOR_FLOOR_SCHEMA_VERSION;
  /** Voice id from the catalog, e.g. `anna`. */
  voice: string;
  /** Language code the line is spoken in, e.g. `en`. */
  locale: string;
  /** The exact text spoken, verbatim. */
  line: string;
  /** Calendar day of the capture, `YYYY-MM-DD`. */
  capturedOn: string;
  /** One sentence: endpoint, tool or person, so a reader can repeat it. */
  producedBy: string;
  method: VendorFloorMethod;
  vendor: {
    name: string;
    /** The vendor-side voice id, e.g. `aai-anna`. */
    voiceId: string;
    /** The vendor-side model that spoke, e.g. `assemblyai-tts-1`. */
    model: string;
  };
  audio: {
    /** File name beside this sidecar. */
    file: string;
    sha256: string;
    container: "wav";
    sampleRate: number;
    channels: number;
    bitsPerSample: number;
  };
};

export type VendorFloorErrorCode =
  | "vendor-floor-missing"
  | "vendor-floor-sidecar-invalid"
  | "vendor-floor-unreadable"
  | "vendor-floor-audio-mismatch"
  | "vendor-floor-evidence-mismatch";

/** A refused floor. A caller can branch on `code`; nothing is assumed. */
export class VendorFloorError extends Error {
  constructor(
    readonly code: VendorFloorErrorCode,
    message: string,
  ) {
    super(message);
    this.name = "VendorFloorError";
  }
}

export type VendorFloor = {
  provenance: VendorFloorProvenance;
  /** The same decode the comparison performs on every capture. */
  audio: DecodedAudio;
  path: string;
  sidecarPath: string;
};

/** One committed floor per voice and Locale, so a subject's floor is a path. */
export function vendorFloorFileName(
  voice: string = VENDOR_FLOOR_VOICE,
  locale: string = VENDOR_FLOOR_LOCALE,
): string {
  return `${voice}-${locale}.wav`;
}

function sidecarName(wavFile: string): string {
  return wavFile.replace(/\.wav$/, ".json");
}

function invalid(where: string, detail: string): VendorFloorError {
  return new VendorFloorError(
    "vendor-floor-sidecar-invalid",
    `vendor floor sidecar invalid: ${where}: ${detail}.`,
  );
}

function requiredString(value: unknown, field: string, where: string): string {
  if (typeof value !== "string" || value.trim().length === 0) {
    throw invalid(where, `"${field}" must be a non-empty string`);
  }
  return value;
}

function requiredPositiveInt(value: unknown, field: string, where: string): number {
  if (typeof value !== "number" || !Number.isInteger(value) || value <= 0) {
    throw invalid(where, `"${field}" must be a positive integer`);
  }
  return value;
}

function isCalendarDay(value: string): boolean {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const parsed = new Date(`${value}T00:00:00Z`);
  return !Number.isNaN(parsed.valueOf()) && parsed.toISOString().slice(0, 10) === value;
}

function objectAt(value: unknown, field: string, where: string): Record<string, unknown> {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    throw invalid(where, `"${field}" must be an object`);
  }
  return value as Record<string, unknown>;
}

function parseProvenance(raw: unknown, where: string): VendorFloorProvenance {
  const root = objectAt(raw, "sidecar", where);
  if (root.schemaVersion !== VENDOR_FLOOR_SCHEMA_VERSION) {
    throw invalid(where, `"schemaVersion" must be ${VENDOR_FLOOR_SCHEMA_VERSION}`);
  }

  const voice = requiredString(root.voice, "voice", where);
  const locale = requiredString(root.locale, "locale", where);
  const line = requiredString(root.line, "line", where);
  const capturedOn = requiredString(root.capturedOn, "capturedOn", where);
  if (!isCalendarDay(capturedOn)) {
    throw invalid(where, `"capturedOn" must be a real calendar day as YYYY-MM-DD, got ${capturedOn}`);
  }
  const producedBy = requiredString(root.producedBy, "producedBy", where);
  const method = requiredString(root.method, "method", where);
  if (!(VENDOR_FLOOR_METHODS as readonly string[]).includes(method)) {
    throw invalid(where, `"method" must be one of ${VENDOR_FLOOR_METHODS.join(", ")}`);
  }

  const vendor = objectAt(root.vendor, "vendor", where);
  const audio = objectAt(root.audio, "audio", where);
  const sha256 = requiredString(audio.sha256, "audio.sha256", where);
  if (!/^[0-9a-f]{64}$/.test(sha256)) {
    throw invalid(where, `"audio.sha256" must be 64 lowercase hex characters`);
  }
  if (audio.container !== "wav") {
    throw invalid(where, `"audio.container" must be "wav"`);
  }

  return {
    schemaVersion: VENDOR_FLOOR_SCHEMA_VERSION,
    voice,
    locale,
    line,
    capturedOn,
    producedBy,
    method: method as VendorFloorMethod,
    vendor: {
      name: requiredString(vendor.name, "vendor.name", where),
      voiceId: requiredString(vendor.voiceId, "vendor.voiceId", where),
      model: requiredString(vendor.model, "vendor.model", where),
    },
    audio: {
      file: requiredString(audio.file, "audio.file", where),
      sha256,
      container: "wav",
      sampleRate: requiredPositiveInt(audio.sampleRate, "audio.sampleRate", where),
      channels: requiredPositiveInt(audio.channels, "audio.channels", where),
      bitsPerSample: requiredPositiveInt(audio.bitsPerSample, "audio.bitsPerSample", where),
    },
  };
}

type PcmDescription = Pick<AudioFacts, "sampleRate" | "channels" | "bitsPerSample">;

function describeFormat(facts: PcmDescription): string {
  return `${facts.sampleRate} Hz/${facts.channels} ch/${facts.bitsPerSample}-bit`;
}

function factsMismatch(
  path: string,
  label: string,
  actual: AudioFacts,
): VendorFloorError {
  return new VendorFloorError(
    "vendor-floor-audio-mismatch",
    `vendor floor audio mismatch: ${path}: the sidecar says ${label}, the file is ${describeFormat(actual)}. ` +
      `Recapture with \`${VENDOR_FLOOR_COMMAND}\` rather than editing either file.`,
  );
}

/**
 * Load the committed floor for one voice and Locale.
 *
 * Throws `VendorFloorError` by name rather than returning an empty or default
 * floor: a comparison with no floor is a comparison that cannot fail.
 */
export function loadVendorFloor(
  options: { directory?: string; voice?: string; locale?: string } = {},
): VendorFloor {
  const directory = options.directory ?? VENDOR_FLOOR_DIR;
  const voice = options.voice ?? VENDOR_FLOOR_VOICE;
  const locale = options.locale ?? VENDOR_FLOOR_LOCALE;
  const fileName = vendorFloorFileName(voice, locale);
  const path = resolve(directory, fileName);
  const sidecarPath = resolve(directory, sidecarName(fileName));

  const absent = [path, sidecarPath].filter((candidate) => !existsSync(candidate));
  if (absent.length > 0) {
    throw new VendorFloorError(
      "vendor-floor-missing",
      `vendor floor missing: ${absent.join(" and ")}. A floor is committed evidence, never an empty default. ` +
        `Capture one with \`${VENDOR_FLOOR_COMMAND}\`, or register an owner-supplied playground recording with ` +
        `\`${VENDOR_FLOOR_COMMAND} --from-recording <file> --captured-on YYYY-MM-DD\`.`,
    );
  }

  let sidecarText: string;
  try {
    sidecarText = readFileSync(sidecarPath, "utf8");
  } catch (error) {
    throw new VendorFloorError(
      "vendor-floor-unreadable",
      `vendor floor unreadable: ${sidecarPath}: ${error instanceof Error ? error.message : String(error)}.`,
    );
  }

  let raw: unknown;
  try {
    raw = JSON.parse(sidecarText);
  } catch (error) {
    throw invalid(sidecarPath, error instanceof Error ? error.message : String(error));
  }
  const provenance = parseProvenance(raw, sidecarPath);
  if (provenance.voice !== voice || provenance.locale !== locale) {
    throw invalid(
      sidecarPath,
      `it names ${provenance.voice}/${provenance.locale}, but ${fileName} is ${voice}/${locale}`,
    );
  }
  if (basename(provenance.audio.file) !== fileName) {
    throw invalid(sidecarPath, `"audio.file" must name ${fileName}, got ${provenance.audio.file}`);
  }

  let bytes: Buffer;
  try {
    bytes = readFileSync(path);
  } catch (error) {
    throw new VendorFloorError(
      "vendor-floor-unreadable",
      `vendor floor unreadable: ${path}: ${error instanceof Error ? error.message : String(error)}.`,
    );
  }

  let audio: DecodedAudio;
  try {
    audio = decodeWav(bytes);
  } catch (error) {
    const reason =
      error instanceof AudioFactsError ? error.message : error instanceof Error ? error.message : String(error);
    throw new VendorFloorError(
      "vendor-floor-unreadable",
      `vendor floor unreadable: ${path}: ${reason}. The comparison reads PCM16 WAV; capture one with \`${VENDOR_FLOOR_COMMAND}\`.`,
    );
  }

  const actualSha = createHash("sha256").update(bytes).digest("hex");
  if (actualSha !== provenance.audio.sha256) {
    throw new VendorFloorError(
      "vendor-floor-audio-mismatch",
      `vendor floor audio mismatch: ${path}: sha256 ${actualSha} does not match the sidecar's ` +
        `${provenance.audio.sha256}. Recapture with \`${VENDOR_FLOOR_COMMAND}\` rather than editing either file.`,
    );
  }

  if (
    audio.facts.sampleRate !== provenance.audio.sampleRate ||
    audio.facts.channels !== provenance.audio.channels ||
    audio.facts.bitsPerSample !== provenance.audio.bitsPerSample
  ) {
    throw factsMismatch(path, describeFormat(provenance.audio), audio.facts);
  }

  return { provenance, audio, path, sidecarPath };
}

/**
 * The floor as an artifact records it (ticket 126): the committed file's path
 * and sha256 plus the provenance that says which voice, locale and day it is.
 * No samples, no line text — the artifact is machine-readable evidence, and the
 * WAV is a committed capture read through {@link loadVendorFloor}.
 */
export type VendorFloorEvidence = {
  /** The committed capture's path. */
  path: string;
  /** Its sha256, as the sidecar records and the loader re-checks. */
  sha256: string;
  voice: string;
  locale: string;
  capturedOn: string;
  method: VendorFloorMethod;
};

/**
 * Copy the evidence fields out of a loaded floor. The values come from the
 * committed sidecar the loader already verified against the audio, so a caller
 * never restates a hash from memory or from a second measurement.
 */
export function vendorFloorEvidence(floor: VendorFloor): VendorFloorEvidence {
  return {
    path: floor.path,
    sha256: floor.provenance.audio.sha256,
    voice: floor.provenance.voice,
    locale: floor.provenance.locale,
    capturedOn: floor.provenance.capturedOn,
    method: floor.provenance.method,
  };
}

/**
 * Refuse a floor record that is not the committed evidence (ticket 126). A
 * recorded floor naming another file, another voice or another hash is a
 * recomputed or replaced baseline: the comparison would then judge a reference
 * against audio nobody committed, so the record is refused by name instead.
 */
export function assertVendorFloorEvidenceIsCommitted(
  recorded: VendorFloorEvidence,
  committed: VendorFloorEvidence,
): void {
  const differs: string[] = [];
  if (recorded.path !== committed.path) differs.push(`path ${recorded.path} vs ${committed.path}`);
  if (recorded.sha256 !== committed.sha256) {
    differs.push(`sha256 ${recorded.sha256} vs ${committed.sha256}`);
  }
  if (recorded.voice !== committed.voice || recorded.locale !== committed.locale) {
    differs.push(
      `voice ${recorded.voice}/${recorded.locale} vs ${committed.voice}/${committed.locale}`,
    );
  }
  if (differs.length > 0) {
    throw new VendorFloorError(
      "vendor-floor-evidence-mismatch",
      `vendor floor evidence mismatch: the artifact records ${differs.join(", ")}, which is not the committed floor. ` +
        `The floor is ${committed.voice}/${committed.locale} at ${committed.path}; it is read from the ` +
        `committed evidence, never recomputed with a different method or replaced by a local render.`,
    );
  }
}

/** A reader-facing one-liner set, for scripts and evidence notes. */export function formatVendorFloor(floor: VendorFloor): string {
  const { provenance, audio, path } = floor;
  const seconds = audio.facts.durationSeconds.toFixed(2);
  return [
    `vendor floor ${provenance.voice}/${provenance.locale} — ${seconds} s, ${describeFormat(audio.facts)}`,
    `  line  "${provenance.line}"`,
    `  date  ${provenance.capturedOn}`,
    `  how   ${provenance.producedBy} (${provenance.vendor.model}, ${provenance.vendor.voiceId})`,
    `  file  ${path}`,
    `  sha256 ${provenance.audio.sha256}`,
  ].join("\n");
}
